 public function update(int$id,array$quantities,string$issueDate,int$userId):void{$note=$this->editable($id);if(!$quantities)throw new RuntimeException('Capture al menos una cantidad a acreditar.');try{$normalizer=new FiscalIssueDateNormalizer();try{$issueDate=$normalizer->normalizeTransport($issueDate);}catch(RuntimeException$transportError){if($transportError->getMessage()!=='FISCAL_ISSUE_DATE_INVALID')throw$transportError;$issueDate=$normalizer->parseCanonical($issueDate)->format(FiscalIssueDateNormalizer::PERSISTENCE);}(new FiscalIssueDatePolicy())->validate($issueDate);}catch(RuntimeException$e){throw new RuntimeException($this->issueDateMessage($e->getMessage()));}$this->db->transBegin();try{foreach($quantities as$itemId=>$quantity){$line=$this->db->table('fiscal_credit_note_items')->where(['id'=>(int)$itemId,'fiscal_credit_note_id'=>$id])->get(1)->getRow();if(!$line)continue;$source=$this->db->table('fiscal_document_items')->where('id',$line->source_fiscal_document_item_id)->get(1)->getRow();$max=bcsub((string)$source->quantity,(new CreditNoteBalanceService($this->db))->creditedItemQuantity((int)$source->id),6);$q=bcadd((string)$quantity,'0',6);if(bccomp($q,'0',6)<=0||bccomp($q,$max,6)>0)throw new RuntimeException('La cantidad acreditada excede la disponible del concepto.');$this->saveLine($id,$source,$q,get_current_utc_time(),(int)$line->id);}$this->db->table('fiscal_credit_notes')->where('id',$id)->update(['issue_date'=>$issueDate,'updated_at'=>get_current_utc_time()]);$this->recalculate($id);$this->assertAmountAvailable($id);$this->invalidatePreparedDocument($note);$this->db->transCommit();}catch(Throwable$e){$this->db->transRollback();throw$e;}}
