 public function context(int$id):array{$note=$this->db->table('fiscal_credit_notes n')->select('n.*,d.series source_series,d.folio source_folio,d.total source_total,s.uuid source_uuid,r.legal_name receiver_name,r.rfc receiver_rfc,r.tax_regime_code receiver_regime,r.fiscal_postal_code receiver_postal')->join('fiscal_documents d','d.id=n.source_fiscal_document_id')->join('fiscal_document_stamps s','s.fiscal_document_id=d.id')->join('fiscal_document_receivers r','r.fiscal_document_id=d.id')->where(['n.id'=>$id,'n.deleted'=>0])->get(1)->getRow();if(!$note)throw new RuntimeException('La Nota de Crédito no existe.');$items=$this->db->table('fiscal_credit_note_items n')->select('n.*,i.product_service_code,i.identification_number,i.unit_code,i.unit_name,i.description,i.tax_object_code,i.quantity source_quantity,i.unit_value source_unit_value,i.gross_amount source_gross_amount,i.discount source_discount,i.line_total source_line_total')->join('fiscal_document_items i','i.id=n.source_fiscal_document_item_id')->where(['n.fiscal_credit_note_id'=>$id,'n.deleted'=>0])->orderBy('i.line_number')->get()->getResult();foreach($items as$item){$item->tax_summary=[];$ratio=bcdiv((string)$item->quantity,(string)$item->source_quantity,12);foreach($this->db->table('fiscal_document_item_taxes')->where('fiscal_document_item_id',$item->source_fiscal_document_item_id)->orderBy('sort_order')->get()->getResult()as$tax){$item->tax_summary[]=['type'=>(string)$tax->tax_type,'code'=>(string)$tax->tax_code,'factor'=>(string)$tax->factor_type,'rate'=>(string)$tax->rate_or_quota,'source_amount'=>(string)$tax->amount,'amount'=>bcmul((string)$tax->amount,$ratio,6)];}}$stamp=$note->fiscal_document_id?$this->db->table('fiscal_document_stamps')->where('fiscal_document_id',$note->fiscal_document_id)->get(1)->getRow():null;$fiscal=$note->fiscal_document_id?$this->db->table('fiscal_documents')->where('id',$note->fiscal_document_id)->get(1)->getRow():null;return compact('note','items','stamp','fiscal')+['availabl