 public function fiscalSquare(int$id):array{$xml=$this->buildXml($id);$dom=new DOMDocument();if(!$dom->loadXML($xml))throw new RuntimeException('No fue posible validar el XML fiscal de la Nota.');$root=$dom->documentElement;$subtotal=(string)$root->getAttribute('SubTotal');$discount=$root->hasAttribute('Descuento')?(string)$root->getAttribute('Descuento'):'0.00';$transferred=$withheld='0.00';foreach($root->childNodes as$child)if($child instanceof \DOMElement&&$child->localName==='Impuestos'){$transferred=$child->hasAttribute('TotalImpuestosTrasladados')?(string)$child->getAttribute('TotalImpuestosTrasladados'):'0.00';$withheld=$child->hasAttribute('TotalImpuestosRetenidos')?(string)$child->getAttribute('TotalImpuestosRetenidos'):'0.00';}$total=(string)$root->getAttribute('Total');$calculator=new CreditNoteFiscalCalculator();$calculated=$calculator->round(bcsub(bcadd(bcsub($subtotal,$discount,6),$transferred,6),$withheld,6),2);$difference=bcsub($total,$calculated,2);return compact('subtotal','discount','transferred','withheld','calculated','total','difference')+['valid'=>bccomp($difference,'0',2)===0];} public function preview(int$id):array{$review=$this->review($id);if(!$review['ready'])throw new RuntimeException(implode(' ',$review['errors']));return['xml'=>$this->buildXml($id),'context'=>$this->contextWithoutReview($id)];}
