 private function recalculate(int$id):void{$r=$this->db->table('fiscal_credit_note_items')->select('SUM(subtotal) subtotal,SUM(discount) discount,SUM(transferred_tax_total) tra,SUM(withheld_tax_total) wh,SUM(total) total',false)->where(['fiscal_credit_note_id'=>$id,'deleted'=>0])->get()->getRow();$this->db->table('fiscal_credit_notes')->where('id',$id)->update(['subtotal'=>$r->subtotal??0,'discount'=>$r->discount??0,'transferred_tax_total'=>$r->tra??0,'withheld_tax_total'=>$r->wh??0,'total'=>$r->total??0,'updated_at'=>get_current_utc_time()]);}
 private function assertAmountAvailable(int$id):void{$n=$this->db->table('fiscal_credit_notes')->where('id',$id)->get(1)->getRow();$available=(new CreditNoteBalanceService($this->db))->available((int)$n->source_fiscal_document_id);if(bccomp((string)$n->total,$available,6)>0)throw new RuntimeException('El total recalculado de la Nota excede el saldo acreditable de la factura.');}
 private function lines(int$id):array{$out=[];$calculator=new CreditNoteFiscalCalculator();foreach($this->db->table('fiscal_credit_note_items')->where(['fiscal_credit_note_id'=>$id,'deleted'=>0])->get()->getResult()as$l){$s=$this->db->table('fiscal_document_items')->where('id',$l->source_fiscal_document_item_id)->get(1)->getRow();$calc=$calculator->line($s,(string)$l->quantity,$this->sourceTaxes((int)$s->id));$out[]=['line'=>$l,'source'=>$s,'taxes'=>$calc['taxes']]+$calc;}return$out;}
 private function sourceTaxes(int$id):array{return$this->db->table('fiscal_document_item_taxes')->where('fiscal_document_item_id',$id)->orderBy('sort_order')->get()->getResult();} private function contextWithoutReview(int$id):array{$n=$this->db->table('fiscal_credit_notes')->where(['id'=>$id,'deleted'=>0])->get(1)->getRow();if(!$n)throw new RuntimeException('La Nota no existe.');$s=$this->source((int)$n->source_fiscal_document_id);$issuer=$this->db->table('fiscal_document_issuers')->where('fiscal_document_id',$s->id)->get(1)->getRow();$receiver=$this->db->table('fiscal_document_receivers')->where('fiscal_document_id',$s->id)->get(1)->getRow();return['note'=>$n,'source'=>$s,'issuer'=>$issuer,'receiver'=>$receiver,'lines'=>$this->lines($id)];}
 private function invalidatePreparedDocument(object$note):void{if(empty($note->fiscal_document_id))return;$documentId=(int)$note->fiscal_document_id;if($this->db->table('fiscal_document_stamps')->where('fiscal_document_id',$documentId)->countAllResults()>0)return;$this->db->table('fiscal_documents')->where('id',$documentId)->update(['status'=>'rejected','updated_at'=>get_current_utc_time()]);$this->db->table('fiscal_credit_notes')->where('id',$note->id)->update(['fiscal_document_id'=>null,'status'=>'draft','updated_at'=>get_current_utc_time()]);} private function issueDateMessage(string$code):string{return match($code){'FISCAL_ISSUE_DATE_REQUIRED'=>'La fecha de emisión es obligatoria.','FISCAL_ISSUE_DATE_FUTURE'=>'La fecha de emisión no puede estar en el futuro.','FISCAL_ISSUE_DATE_TOO_OLD'=>'La fecha de emisión está fuera de la ventana fiscal permitida de '.config('Fiscal')->maxIssueAgeHours.' horas.',default=>'La fecha de emisión no es válida. Use la fecha y hora local mostradas por el sistema.'};}
 private function attrs($e,array$a):void{foreach($a as$k=>$v)if($v!==null&&$v!=='')$e->setAttribute($k,(string)$v);}private function money($v):string{return(new CreditNoteFiscalCalculator())->round((string)$v,2);}private function decimal($v):string{return bcadd((string)$v,'0',6);}
 private function appendGlobalTaxes(DOMDocument$d,$root,int$id,object$n):void{$groups=[];foreach($this->lines($id)as$entry)foreach($entry['taxes']as$t){$s=$t['source'];$key=$s->tax_type.'|'.$s->tax_code.'|'.$s->factor_type.'|'.$s->rate_or_quota;if(!isset($groups[$key]))$groups[$key]=['source'=>$s,'base'=>'0','amount'=>'0'];$groups[$key]['base']=bcadd($groups[$key]['base'],$t['base'],6);$groups[$key]['amount']=bcadd($groups[$key]['amount'],$t['amount'],6);}if(!$groups)return;$g=$d->createElementNS($root->namespaceURI,'cfdi:Impuestos');if(bccomp($n->withheld_tax_total,'0',6)>0)$g->setAttribute('TotalImpuestosRetenidos',$this->money($n->withheld_tax_total));if(bccomp($n->transferred_tax_total,'0',6)>0)$g->setAttribute('TotalImpuestosTrasladados',$this->money($n->transferred_tax_total));foreach(['withheld'=>'Retenciones','transferred'=>'Traslados']as$type=>$name){$rows=array_filter($groups,fn($x)=>$x['source']->tax_type===$type);if(!$rows)continue;$list=$d->createElementNS($root->namespaceURI,'cfdi:'.$name);foreach($rows as$x){$s=$x['source'];$node=$d->createElementNS($root->namespaceURI,'cfdi:'.($type==='withheld'?'Retencion':'Traslado'));$this->attrs($node,$type==='withheld'?['Impuesto'=>$s->tax_code,'Importe'=>$this->money($x['amount'])]:['Base'=>$this->money($x['base']),'Impuesto'=>$s->tax_code,'TipoFactor'=>$s->factor_type,'TasaOCuota'=>$s->factor_type==='Exento'?null:$this->decimal($s->rate_or_quota),'Importe'=>$s->factor_type==='Exento'?null:$this->money($x['amount'])]);$list->appendChild($node);}$g->appendChild($list);}$root->appendChild($g);}
 private function insertTaxTotals(int$documentId,int$noteId,string$now):void{$groups=[];foreach($this->lines($noteId)as$entry)foreach($entry['taxes']as$t){$s=$t['source'];$key=$s->tax_type.'|'.$s->tax_code.'|'.$s->factor_type.'|'.$s->rate_or_quota;if(!isset($groups[$key]))$groups[$key]=['s'=>$s,'base'=>'0','amount'=>'0'];$groups[$key]['base']=bcadd($groups[$key]['base'],$t['base'],6);$groups[$key]['amount']=bcadd($groups[$key]['amount'],$t['amount'],6);}foreach($groups as$x)$this->db->table('fiscal_document_tax_totals')->insert(['fiscal_document_id'=>$documentId,'tax_code'=>$x['s']->tax_code,'tax_type'=>$x['s']->tax_type,'factor_type'=>$x['s']->factor_type,'rate_or_quota'=>$x['s']->rate_or_quota,'taxable_base'=>$x['base'],'amount'=>$x['amount'],'created_at'=>$now]);}
 private function activeCertificate(int$id):object{$d=$this->db->table('fiscal_documents')->where('id',$id)->get(1)->getRow();$now=get_current_utc_time();$c=$this->db->table('fiscal_issuer_certificates')->where(['issuer_profile_id'=>$d->issuer_profile_id,'status'=>'valid','deleted'=>0])->where('valid_from <=',$now)->where('valid_to >=',$now)->orderBy('valid_to','DESC')->get(1)->getRow();if(!$c)throw new RuntimeException('El emisor no tiene un CSD utilizable.');return$c;}
}